"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[57539],{3331:(e,r,n)=>{n.d(r,{R:()=>o,x:()=>l});var t=n(36672);const i={},s=t.createContext(i);function o(e){const r=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function l(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),t.createElement(s.Provider,{value:r},e.children)}},68825:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>a,contentTitle:()=>l,default:()=>g,frontMatter:()=>o,metadata:()=>t,toc:()=>k});const t=JSON.parse('{"id":"2023/04/06","title":"2023-04-06","description":"Remembering Bob Lee","source":"@site/i18n/nb/docusaurus-plugin-content-docs/current/2023/04/06.md","sourceDirName":"2023/04","slug":"/2023/04/06","permalink":"/nb/2023/04/06","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nb/docusaurus-plugin-content-docs//current/2023/04/06.md","tags":[],"version":"current","frontMatter":{"localized_date":"6. april 2023","top_news":"Remembering Bob Lee"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-07","permalink":"/nb/2023/04/07"},"next":{"title":"2023-04-05","permalink":"/nb/2023/04/05"}}');var i=n(23420),s=n(3331);const o={localized_date:"6. april 2023",top_news:"Remembering Bob Lee"},l="2023-04-06",a={},k=[{value:"Remembering Bob Lee",id:"remembering-bob-lee",level:2},{value:"Bob Lee, tidligere teknologidirekt\xf8r i Square, er d\xf8d etter \xe5 ha blitt knivstukket i San Francisco.",id:"bob-lee-tidligere-teknologidirekt\xf8r-i-square-er-d\xf8d-etter-\xe5-ha-blitt-knivstukket-i-san-francisco",level:2},{value:"Fortell iOS lar operat\xf8rer legge til WiFi-nettverk som du ikke kan hindre deg i \xe5 bli med i.",id:"fortell-ios-lar-operat\xf8rer-legge-til-wifi-nettverk-som-du-ikke-kan-hindre-deg-i-\xe5-bli-med-i",level:2},{value:"Dyp l\xe6ring gir grunnlag for stabil diffusjon",id:"dyp-l\xe6ring-gir-grunnlag-for-stabil-diffusjon",level:2},{value:"CAN-injeksjon: N\xf8kkelfritt biltyveri",id:"can-injeksjon-n\xf8kkelfritt-biltyveri",level:2},{value:"Firefox-ingeni\xf8rer oppdager en Windows Defender-feil som for\xe5rsaker h\xf8y CPU-bruk.",id:"firefox-ingeni\xf8rer-oppdager-en-windows-defender-feil-som-for\xe5rsaker-h\xf8y-cpu-bruk",level:2},{value:"Segment Anything Model (SAM) kan &quot;klippe ut&quot; ethvert objekt i et bilde.",id:"segment-anything-model-sam-kan-klippe-ut-ethvert-objekt-i-et-bilde",level:2},{value:"Bitcoin-hvitboken er skjult i alle kopier av macOS.",id:"bitcoin-hvitboken-er-skjult-i-alle-kopier-av-macos",level:2},{value:"Tidligere Square CTO Bob Lee knivstukket til d\xf8de i sentrum av San Francisco.",id:"tidligere-square-cto-bob-lee-knivstukket-til-d\xf8de-i-sentrum-av-san-francisco",level:2},{value:"Argumenter for \xe5 utestenge barn fra sosiale medier.",id:"argumenter-for-\xe5-utestenge-barn-fra-sosiale-medier",level:2},{value:"Dang kommer snart til \xe5 ha 65 535 karma-poeng.",id:"dang-kommer-snart-til-\xe5-ha-65-535-karma-poeng",level:2},{value:"Nevrale nettverk: Fra null til helt",id:"nevrale-nettverk-fra-null-til-helt",level:2},{value:"Et triks for \xe5 oppn\xe5 flyt: La arbeidet ditt v\xe6re \xf8delagt",id:"et-triks-for-\xe5-oppn\xe5-flyt-la-arbeidet-ditt-v\xe6re-\xf8delagt",level:2},{value:"Er RAM slettet f\xf8r bruk i en annen LXC-container?",id:"er-ram-slettet-f\xf8r-bruk-i-en-annen-lxc-container",level:2},{value:"Perspektiv: Open Source WebAssembly-drevet BI",id:"perspektiv-open-source-webassembly-drevet-bi",level:2},{value:"Grid World",id:"grid-world",level:2},{value:"OpenAI Tokenizer",id:"openai-tokenizer",level:2},{value:"Tabloid - programmeringsspr\xe5ket for clickbait-overskriftene",id:"tabloid---programmeringsspr\xe5ket-for-clickbait-overskriftene",level:2},{value:"GPT4 simulerer en FTP-server p\xe5 ftp.disney.com.",id:"gpt4-simulerer-en-ftp-server-p\xe5-ftpdisneycom",level:2},{value:"Bruke mmap for \xe5 f\xe5 LLaMA til \xe5 laste raskere.",id:"bruke-mmap-for-\xe5-f\xe5-llama-til-\xe5-laste-raskere",level:2}];function d(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"2023-04-06",children:"2023-04-06"})}),"\n",(0,i.jsx)(r.h2,{id:"remembering-bob-lee",children:"Remembering Bob Lee"}),"\n",(0,i.jsx)(r.p,{children:"Teknologisamfunnet s\xf8rger over tapet av Bob Lee, en velkjent skikkelse i bransjen. Lee var en forkjemper for Java, etter \xe5 ha jobbet hos Google og Square, og var kjent for sitt arbeid med rammeverket Guice dependency injection. Han var ogs\xe5 en av grunnleggerne av Android Alliance, et initiativ som tar sikte p\xe5 \xe5 fremme innovasjon i Android-\xf8kosystemet. Lees bidrag til teknologiverden var allment anerkjent, og han vil bli sterkt savnet av sine kolleger og jevnaldrende. Mange har delt sine kondolanser p\xe5 sosiale medier og minnes Lee som en mentor og venn som alltid tok seg tid til andre. Hvil i fred, Bob Lee."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35457341",children:"Discussion Service"}),".\nBob Lee, medforfatter av Guice og Java-bibliotekene, kjent for sine tekniske ferdigheter, vennlighet og ydmykhet, har g\xe5tt bort. Hans d\xf8d har etterlatt teknologimilj\xf8et i sorg og har f\xe5tt mange til \xe5 dele sine minner og anekdoter om ham. Lees arv av innovasjon og lidenskap har inspirert mange, og hans bidrag til bransjen vil bli savnet. Mens noen kommentarer var negative, delte de fleste positive tanker og erfaringer om Bob."]}),"\n",(0,i.jsx)(r.h2,{id:"bob-lee-tidligere-teknologidirekt\xf8r-i-square-er-d\xf8d-etter-\xe5-ha-blitt-knivstukket-i-san-francisco",children:"Bob Lee, tidligere teknologidirekt\xf8r i Square, er d\xf8d etter \xe5 ha blitt knivstukket i San Francisco."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.sfgate.com/bayarea/article/mill-valley-man-killed-sf-stabbing-17878809.php",children:"Original"}),".\nBob Lee, skaperen av Cash App som Chief Technology Officer i Square, ble identifisert som mannen som ble drept i San Francisco p\xe5 grunn av en knivstikking; hendelsen har sjokkert teknologiverden, med folk som reagerer p\xe5 de plutselige nyhetene. Politiet har ikke foretatt noen arrestasjoner eller gitt ut informasjon om mulige mistenkte. Lee var 43 \xe5r gammel, var grunnleggeren av Cash App, og hadde jobbet som Chief Product Officer i MobileCoin da han d\xf8de."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35448899",children:"Discussion Service"}),".\nTidligere CTO for Square, Bob Lee, drept i San Francisco gnister diskusjon om kriminalitet og styring. Kommentarene dekker velstandsforskjeller, hjeml\xf8shet, gentrifisering og potensielle l\xf8sninger. Diskusjonen tar opp utfordringer knyttet til politiske systemer og up\xe5litelig kriminalitetsstatistikk i amerikanske byer. Brukerne diskuterer potensielle \xe5rsaker til kriminalitet, blant annet massemigrasjon, ulikhet i velstand, p\xe5virkede rettssystemer og politiets manglende reaksjonsevne. Det er ikke nyttig \xe5 sammenligne kriminalitet mellom ulike land eller kulturer. Sp\xf8rsm\xe5let om kriminalitet er komplekst og ikke et resultat av \xe9n enkelt faktor."]}),"\n",(0,i.jsx)(r.h2,{id:"fortell-ios-lar-operat\xf8rer-legge-til-wifi-nettverk-som-du-ikke-kan-hindre-deg-i-\xe5-bli-med-i",children:"Fortell iOS lar operat\xf8rer legge til WiFi-nettverk som du ikke kan hindre deg i \xe5 bli med i."}),"\n",(0,i.jsx)(r.p,{children:'Operativsystemet iOS gj\xf8r det mulig for operat\xf8rer \xe5 legge til WiFi-nettverk som brukerne ikke kan velge bort. Denne funksjonen skaper bekymring blant iPhone-brukere som har begrensede dataabonnementer eller er bekymret for personvernet. Funksjonen er ment \xe5 hjelpe operat\xf8rer med \xe5 lansere WiFi-hotspots, men den gj\xf8r det ogs\xe5 mulig for dem \xe5 legge til offentlige WiFi-nettverk som brukerne uvitende kobler seg til, og som potensielt kan samle inn sensitive data. Brukerne har begrensede muligheter til \xe5 deaktivere funksjonen, inkludert \xe5 deaktivere WiFi helt eller velge "Glem dette nettverket" hver gang de st\xf8ter p\xe5 det. Noen brukere ber Apple om \xe5 legge til mer kontroll over denne funksjonen, mens andre foresl\xe5r \xe5 bruke et VPN for \xe5 beskytte dataene sine.'}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35447486",children:"Discussion Service"}),".\niOS 16.4 gj\xf8r det mulig for operat\xf8rer \xe5 legge til administrerte nettverk p\xe5 enheter, senke mobilkostnadene og forhindre deaktivering av automatisk tilkobling, uten noen annen m\xe5te \xe5 fjerne disse nettverkene p\xe5 enn \xe5 tilbakestille nettverksinnstillingene. Brukere rapporterer at T-Mobile stjeler data og at Wingman-nettverk om bord ikke sl\xe5r seg av, og uttrykker sjokk over at operat\xf8rer dikterer WiFi-tilkoblinger uten at brukerne har noe valg. Det oppst\xe5r debatt om hvordan man kan f\xe5 full kontroll over enheten, og noen brukere anbefaler GrapheneOS for sikkerhetsoppdateringer. Operat\xf8renes WiFi-hotspots kritiseres for \xe5 forstyrre tilkoblinger til lokale enheter, og noen synes funksjonen er nyttig i overfylte omr\xe5der."]}),"\n",(0,i.jsx)(r.h2,{id:"dyp-l\xe6ring-gir-grunnlag-for-stabil-diffusjon",children:"Dyp l\xe6ring gir grunnlag for stabil diffusjon"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://course.fast.ai/Lessons/part2.html",children:"Original"}),'.\n"Practical Deep Learning for Coders - Part 2" er et kurs som best\xe5r av over 30 timers videoinnhold som inkluderer dekning av Stable Diffusion-algoritmen fra bunnen av, i tett samarbeid med eksperter fra Stable.ai og Hugging Face. Kurset gir en grundig dekning av de nyeste teknikkene og g\xe5r utover hva Stable Diffusion inkluderer, noe som gj\xf8r det til et flott l\xe6ringsm\xe5l av mange grunner, men for \xe5 f\xe5 mest mulig ut av dette kurset, b\xf8r du v\xe6re en rimelig trygg dyp l\xe6ringsut\xf8ver. Gjennom kurset vil vi utforske diffusjonsmetoder, implementere v\xe5re egne modeller fra bunnen av, mestre Python-konsepter og PyTorch for \xe5 implementere modellene v\xe5re. Vi vil dekke diffusjonsfundamenter, dyp l\xe6ringsoptimaliserere, Python-konsepter, grunnleggende grunnlag, pseudo-tilfeldige tallgenerering, nevrale nettverksarkitekturer, generative arkitekturer, transformatorer og blandet presisjonstrening.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35449831",children:"Discussion Service"}),".\n'Deep Learning Foundations to Stable Diffusion' utforsker moderne generativ modellering, mens noen anbefaler \xe5 fokusere p\xe5 markedsf\xf8ring. Fast.ai's dypl\xe6ringskurs skaper et programmeringsrammeverk fra bunnen av og anbefales for alle som er interessert i det. Det p\xe5g\xe5r en debatt om de potensielle farene ved avansert kunstig intelligens og betydningen av regulering og etiske hensyn. Kommentatorer foresl\xe5r \xe5 forby AI-produksjon, men det er ikke en langsiktig l\xf8sning med mindre alle land gj\xf8r det. FastAIs kurs har ingen politisk eller religi\xf8st partiske uttalelser, og innholdet anses som f\xf8rsteklasses. Kurset er tilgjengelig for alle med grunnleggende matematikk fra videreg\xe5ende skole og dekker avanserte konsepter."]}),"\n",(0,i.jsx)(r.h2,{id:"can-injeksjon-n\xf8kkelfritt-biltyveri",children:"CAN-injeksjon: N\xf8kkelfritt biltyveri"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://kentindell.github.io/2023/04/03/can-injection/",children:"Original"}),".\nBiltyver bruker en ny teknikk kalt CAN-injeksjon for \xe5 omg\xe5 smarte n\xf8kkelsystemer i moderne biler ved \xe5 utnytte s\xe5rbarheter i CAN-busskommunikasjonsprotokollen. Sofistikerte bilsikkerhetssystemer, inkludert startsperrer, har blitt s\xe5rbare. Tyver bruker en enhet kalt CAN Injector for \xe5 stjele biler uten n\xf8kkelen ved \xe5 injisere falske meldinger i bilens interne kommunikasjonssystem. Enheten koster $ 10 og inneholder en PIC18F-brikke, forh\xe5ndsprogrammert firmware, en transceiver og en ekstra krets. En rask l\xf8sning eller kryptografiske meldinger kan beseire CAN Injector. Ian Haken skisserer flere m\xe5ter bilprodusenter kan bidra til \xe5 sikre biler p\xe5, men kriminell utnyttelse av teknikken er utbredt. Det er et bransjeomfattende problem som krever en oppdatering av ECU-programvaren for \xe5 bekjempe tyver."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35452963",children:"Discussion Service"}),".\nEn n\xf8kkelfri biltyveriteknikk kjent som CAN Injection ble fremhevet p\xe5 Hacker News. Forbrukerne b\xf8r v\xe6re forsiktige med \xe5 kryptere eller signere CAN-bussen, da det kan begrense tredjeparts diagnoseverkt\xf8y og \xf8ke reparasjonskostnadene. CAN-bussen styrer flere kj\xf8ret\xf8yfunksjoner, og bilprodusentene optimaliserer kostnadene hensynsl\xf8st. Bilprodusenter har juridiske krav om \xe5 skille seg fra forhandlere, men noen kommentarer kritiserer deres overholdelse av lovens \xe5nd. Premium-bilmerker bruker ulike sikkerhetstiltak for \xe5 forhindre bilhacking, inkludert startsperrer med riktige kryptografiske protokoller for \xe5 autentisere start-frigj\xf8ringsmeldinger og signerte CAN/FlexRay/Ethernet-rammer for \xe5 forhindre forfalskning av meldinger. Billige biler er m\xe5let fordi de er lette \xe5 stjele, mens dyre biler er m\xe5let for voldelige tyverier. Utnyttelsen som er beskrevet i artikkelen, kan brukes p\xe5 nesten alle ikke-tilkoblede kj\xf8ret\xf8y som er produsert det siste ti\xe5ret. Bruken av CAN-buss i kritiske systemer som luftfart og bilindustrien skyldes at den er enkel \xe5 koble til og kostnadseffektiv."]}),"\n",(0,i.jsx)(r.h2,{id:"firefox-ingeni\xf8rer-oppdager-en-windows-defender-feil-som-for\xe5rsaker-h\xf8y-cpu-bruk",children:"Firefox-ingeni\xf8rer oppdager en Windows Defender-feil som for\xe5rsaker h\xf8y CPU-bruk."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://bugzilla.mozilla.org/show_bug.cgi?id=1441918#c82",children:"Original"}),".\nN/A (Denne teksten er ikke relatert til emnet)."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35458746",children:"Discussion Service"}),".\nFirefox-ingeni\xf8rer fant en Windows Defender-feil som for\xe5rsaker CPU-bruk i Mozillas nettleser. Microsoft lanserer en oppdatering for \xe5 fikse dette. Andre AV-produkter kan ogs\xe5 for\xe5rsake problemer med CPU-bruk. Firefox foretar flere systemanrop enn Chrome av sikkerhetsgrunner. En sammenligning viser at Firefox yter raskere enn Chrome i noen tester. Eksperter diskuterer begrensningene til Defender, foresl\xe5r sandboxing og maskinvare-MFA. Brukere diskuterer effektiviteten til Defender kontra tredjeparts AV-programvare. Noen brukere rapporterer om problemer med Defender som for\xe5rsaker treg filsystemtilgang."]}),"\n",(0,i.jsx)(r.h2,{id:"segment-anything-model-sam-kan-klippe-ut-ethvert-objekt-i-et-bilde",children:'Segment Anything Model (SAM) kan "klippe ut" ethvert objekt i et bilde.'}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://segment-anything.com/",children:"Original"}),".\nSegment Anything Model (SAM) utviklet av Meta AI kan isolere ethvert objekt i et bilde med h\xf8y n\xf8yaktighet. Den kan identifisere og segmentere objekter, selv n\xe5r de er delvis synlige eller tildekket. SAM forbedrer tidligere utviklede modeller som baserte seg p\xe5 plasseringssignaler eller fremtredende objekter. I stedet for \xe5 bruke disse signalene bruker SAM metal\xe6ring, og utnytter en eksisterende modells l\xe6ring, for \xe5 kunne oppdage sm\xe5, skjeve datasett eller usynlige objekter. SAM kan brukes til praktiske anvendelser, som bilderedigering, samt forskning innen datasyn."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35455566",children:"Discussion Service"}),'.\nMeta AIs SAM gj\xf8r det mulig \xe5 generere masker i sanntid for \xe5 "klippe ut" ethvert objekt fra et bilde. Modellens lisensiering og imponerende inferensmuligheter kan gj\xf8re den popul\xe6r blant teknologieksperter. Problemene inkluderer lavere hastighet med RTX 2080ti 11 GB-modellen og begrenset presisjon med gjennomsiktige objekter. Noen ser Meta AIs utgivelsesstrategi som en del av et AR-adopsjonspress. Brukere roser SAMs kostnadsreduksjon for dataanmerkninger, men kritiserer hastigheten og sammenligner den med iOS. Utviklingen kan ogs\xe5 ha potensiell sikkerhetskameraapplikasjon og AdobeAI-integrasjon.']}),"\n",(0,i.jsx)(r.h2,{id:"bitcoin-hvitboken-er-skjult-i-alle-kopier-av-macos",children:"Bitcoin-hvitboken er skjult i alle kopier av macOS."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://waxy.org/2023/04/the-bitcoin-whitepaper-is-hidden-in-every-modern-copy-of-macos/",children:"Original"}),'.\nEn PDF-kopi av Satoshi Nakamotos Bitcoin-hvitbok har blitt oppdaget i alle moderne kopier av macOS siden Mojave i 2018, og kan n\xe5s via et eksempeldokument i Image Capture-verkt\xf8yet. Hvitboken brukes som et eksempeldokument for en enhet kalt "Virtual Scanner II", som enten er skjult eller ikke installert for alle som standard. \xc5rsaken til at den er inkludert er fortsatt uklar, men det kan ha v\xe6rt en praktisk og lett PDF-fil med flere sider for testform\xe5l. Det er sv\xe6rt lite informasjon tilgjengelig p\xe5 nettet om Virtual Scanner II eller inkluderingen av hvitboken i macOS.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35461011",children:"Discussion Service"}),".\nBitcoin-hvitboken er skjult i alle macOS-kopier siden 2019; spekulasjoner om hvorfor den er inkludert, og brukere advarer mot gruvedrift p\xe5 iPhones. Hash-summen samsvarer med den opprinnelige versjonen, men teoriene varierer om hvorfor den er inkludert. Klager oppsto om godkjenning av et pyramidespill, men brukerne presiserer at det er skjult. Apple kan ha inkludert det for enkelhets skyld, men innlegget utl\xf8ser dialog om Bitcoins innvirkning. Brukere kommenterer bildet som brukes i en artikkel, PDF-filst\xf8rrelsen og teknologi som mister sin kunstneriske moro."]}),"\n",(0,i.jsx)(r.h2,{id:"tidligere-square-cto-bob-lee-knivstukket-til-d\xf8de-i-sentrum-av-san-francisco",children:"Tidligere Square CTO Bob Lee knivstukket til d\xf8de i sentrum av San Francisco."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://sfstandard.com/criminal-justice/san-francisco-stabbing-victim-bob-lee-former-cto-square-mobilecoin/",children:"Original"}),".\nTidligere Square CTO Bob Lee ble knivstukket til d\xf8de i sentrum av San Francisco if\xf8lge The Standard. Lee var Chief Product Officer for MobileCoin, et kryptoselskap i San Francisco, og et elsket medlem av Bay Area programvareutvikling og teknologisamfunn. SFPD har ikke gitt ut ytterligere detaljer eller offerets identitet, og ber om \xf8yenvitner og videoopptak for etterforskningen. San Francisco har opplevd 12 drap per 2. april, to mer enn samme periode i fjor. The Standard dekker viktige saker, inkludert strafferettslige sp\xf8rsm\xe5l i San Francisco, og tilbyr nyhetsbrev og en omfattende oversikt over San Franciscos politikk og kultur."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35452426",children:"Discussion Service"}),".\nTidligere Square CTO Bob Lee knivstukket til d\xf8de i San Francisco; kommentarer refererer til nye detaljer."]}),"\n",(0,i.jsx)(r.h2,{id:"argumenter-for-\xe5-utestenge-barn-fra-sosiale-medier",children:"Argumenter for \xe5 utestenge barn fra sosiale medier."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.newyorker.com/news/our-columnists/the-case-for-banning-children-from-social-media",children:"Original"}),".\nDebatten om \xe5 utestenge barn fra sosiale medier p\xe5g\xe5r p\xe5 grunn av bekymringer om avhengighet og negativitet. Noen lovforslag har blitt vedtatt for \xe5 begrense mindre\xe5riges tilgang til sosiale medier og fjerne avhengighetsskapende funksjoner, men dette har konsekvenser for borgerrettighetene og begrenser tilgangen til nyheter og ulike perspektiver, noe som reiser sp\xf8rsm\xe5let om hvordan sosiale medier b\xf8r behandles. Selv om domstolene har sl\xe5tt ned p\xe5 nettbeskyttelse av hensyn til barns sikkerhet, kan det \xe5 opprette meldinger mot avhengighet og juridiske restriksjoner komme i konflikt med rettighetene i grunnloven, og foreldre kan bli n\xf8dt til \xe5 fjerne skjermene fysisk. Beskyttelse av barn p\xe5 nettet er en politisk og kulturell debatt, noe som etterlater liten tillit til myndighetenes evne til \xe5 regulere sosiale medieselskaper."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35447588",children:"Discussion Service"}),".\nEn artikkel tar til orde for \xe5 forby sosiale medier for personer under 18 \xe5r p\xe5 grunn av potensiell narkotikalignende avhengighet; det er vanskelig \xe5 regulere slikt innhold. En debatt om definisjonen og p\xe5virkningen av annonser rettet mot barn gir grunn til bekymring for regulering av reklame. Skadelige virkninger av sosiale medier p\xe5 mental helse og personlig utvikling tas opp, noe som har f\xf8rt til forslag om \xe5 forby sosiale medier og algoritmiske feeder. Et generelt forbud mot sosiale medier blir ikke sett p\xe5 som l\xf8sningen; det er behov for nyanserte tiln\xe6rminger. Discussion Service-brukere diskuterer effektive m\xe5ter \xe5 begrense skjermtid og bekjempe negative effekter p\xe5. Debatten dreier seg om \xe5 finne en balanse mellom individuell frihet og samfunnsansvar. Bekymringer om kontroll over sosiale medier og dopaminfrigj\xf8ring i hjernen f\xf8rer til diskusjoner om \xe5 forby algoritmestyrte sosiale medier. Gjennomf\xf8rbarhet og potensiell krenkelse av personvernet fremheves som bekymringer knyttet til obligatorisk ID-kontroll for kontoer i sosiale medier. Ingen ny teknologi eller st\xf8rre utgivelser diskutert."]}),"\n",(0,i.jsx)(r.h2,{id:"dang-kommer-snart-til-\xe5-ha-65-535-karma-poeng",children:"Dang kommer snart til \xe5 ha 65 535 karma-poeng."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://news.ycombinator.com/user?id=dang",children:"Original"}),".\nDiscussion Service-bruker 'dang' forventes snart \xe5 n\xe5 65 535 karma-poeng, som er maksimumsgrensen p\xe5 grunn av systemets bruk av et signert 16-biters heltall."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35460732",children:"Discussion Service"}),".\nDaniel Gackle, AKA Dang, i ferd med \xe5 n\xe5 65 535 karma. Kommentarfeltet er fylt med ros for Dangs arbeid. Brukere spekulerer i om karma vil rulle over og diskutere \xe5 endre til 32-bit int. Modereringsstil og Y Combinators involvering avh\xf8rt. \xc5 oppn\xe5 h\xf8y karma sett p\xe5 som en m\xe5te \xe5 vise takknemlighet for Dangs arbeid. \xc5 n\xe5 h\xf8yere karma-milep\xe6ler gir flere muligheter p\xe5 Discussion Service, for eksempel upvoting/downvoting."]}),"\n",(0,i.jsx)(r.h2,{id:"nevrale-nettverk-fra-null-til-helt",children:"Nevrale nettverk: Fra null til helt"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://karpathy.ai/zero-to-hero.html",children:"Original"}),'.\nKurset "Nevrale nettverk: Zero to Hero" av Andrej Karpathy l\xe6rer \xe5 bygge nevrale nettverk fra bunnen av i kode. Kurset begynner med det grunnleggende om backpropagation og g\xe5r videre til moderne dype nevrale nettverk som GPT. Kurset fokuserer p\xe5 spr\xe5kmodeller da de er et utmerket sted \xe5 l\xe6re dyp l\xe6ring. Forutsetninger inkluderer solid programmering og matematikk p\xe5 introduksjonsniv\xe5. Kurset inkluderer \xe5 bygge mikrograd, makemore, en MLP og dykke inn i noen av de interne MLP-ene. \xc5 bli en Backprop Ninja og bygge WaveNet er ogs\xe5 dekket. Kurset kulminerer i \xe5 bygge GPT. Videoene gir en trinnvis forklaring og fokuserer p\xe5 \xe5 bygge kompetanse og intuisjon rundt hvordan nevrale nett er optimalisert. Kurset anbefaler seerne \xe5 se de tidligere makemore-videoene for \xe5 v\xe6re komfortable med det autoregressive spr\xe5kmodelleringsrammeverket og grunnleggende om tensorer og PyTorch nn.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35459031",children:"Discussion Service"}),".\nAndrej Karpathys 'Nevrale nettverk: Zero to Hero'-kurset f\xe5r over 300 poeng p\xe5 Hacker News p\xe5 6 timer. Discussion Service-brukere roser undervisningsstilen hans og anbefaler koding etter \xe5 ha sett videoene. Hans peer-ledede ML-kurs f\xe5r positive tilbakemeldinger til tross for at han ikke nevner det. Python-spesifikk syntaks i videoer kan utfordre noen brukere. En diskusjon evaluerer kursets vekt p\xe5 logistisk regresjon og perceptron. Deltakerne syntes kurset var lett \xe5 forst\xe5 og anbefaler andre kurs for nybegynnere. Noen brukere stiller sp\xf8rsm\xe5l ved webutvikleres minimumskunnskaper, og en bruker har en teori om koblingen mellom ML og Hopf-algebra."]}),"\n",(0,i.jsx)(r.h2,{id:"et-triks-for-\xe5-oppn\xe5-flyt-la-arbeidet-ditt-v\xe6re-\xf8delagt",children:"Et triks for \xe5 oppn\xe5 flyt: La arbeidet ditt v\xe6re \xf8delagt"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://census.dev/blog/an-on-ramp-to-flow",children:"Original"}),'.\nArtikkelen diskuterer vanskeligheten med \xe5 komme i en tilstand av "flyt" i ingeni\xf8roppgaver og gir et triks for \xe5 komme inn i flyt igjen. Forfatteren foresl\xe5r \xe5 forlate arbeidet i en tilstand som \xe5penbart er \xf8delagt, men som er lett \xe5 fikse f\xf8r man g\xe5r bort. Dette gir et klart utgangspunkt n\xe5r man kommer tilbake til arbeidet, og skaper fremdrift og selvtillit. Artikkelen erkjenner at denne tiln\xe6rmingen kanskje ikke er universell eller anvendelig i teammilj\xf8er, men inviterer til tilbakemeldinger om andre triks. Det er ogs\xe5 en kort omtale av Census Engineering og jobbmuligheter.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35456059",children:"Discussion Service"}),'.\nDiscussion Service-brukere deler tips for \xe5 n\xe5 flyttilstand ved \xe5 la arbeidet v\xe6re uferdig, inkludert metoden "parkere i nedoverbakke". En ingeni\xf8rdirekt\xf8r innf\xf8rte \xe5 forlate arbeidet innen kl. 18.00 for \xe5 unng\xe5 utbrenthet, men avsluttet det p\xe5 grunn av syken\xe6rv\xe6r. Brukerne diskuterer fordelene og risikoene ved strenge tidsregler og endring av arbeidskulturen. Noen deler produktivitetstips som \xe5 skrive ned neste trinn og praktisere TDD. \xc5 la koden ligge i en "\xf8delagt" tilstand kan hjelpe med \xe5 gjenoppta senere, men det har blandede resultater.']}),"\n",(0,i.jsx)(r.h2,{id:"er-ram-slettet-f\xf8r-bruk-i-en-annen-lxc-container",children:"Er RAM slettet f\xf8r bruk i en annen LXC-container?"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://security.stackexchange.com/questions/269507/is-ram-wiped-before-use-in-another-lxc-container",children:"Original"}),".\nEt innlegg p\xe5 Information Security Stack Exchange sp\xf8r om RAM t\xf8rkes f\xf8r bruk i en annen LXC-container, noe som f\xf8rer til en diskusjon om RAM-overprovisioning i LXC, med en bruker som kommenterer at minne tildelt en tidligere prosess i en container er ryddet. Et innlegg p\xe5 Hacker News g\xe5r videre og diskuterer delte biblioteker og beskyttelse av brukernavnerom, og et svar avklarer at sider er tomme f\xf8r tildeling, overprovisjonering ikke for\xe5rsaker deling, og LXC-minne tildeles prosesser via navnerom, men prosesser er atskilt fra vertsressurser. Til slutt bemerkes det at glibc-basert minneh\xe5ndtering ikke inneb\xe6rer opprydding, og at frie sider kan inneholde data."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35451863",children:"Discussion Service"}),".\nBrukere p\xe5 Hacker News diskuterte effektiviteten og n\xf8dvendigheten av automatisk nullstilling av minne i Linux, og noen foreslo alternative metoder for \xe5 t\xf8mme ubrukt minne. En bruker p\xe5pekte at problemet ligger i utformingen av UNIX' fork()-systemkall, og at mange minnekrevende programmer fortsatt sliter med OOM-problemer. Andre kommentarer diskuterer forskjellene mellom overcommit og ikke-overcommit minnetildeling i Linux og viktigheten av \xe5 sette grenser. Artikkelen gir nyanserte perspektiver p\xe5 Linux-minnetildeling og er rettet mot eksperter p\xe5 omr\xe5det."]}),"\n",(0,i.jsx)(r.h2,{id:"perspektiv-open-source-webassembly-drevet-bi",children:"Perspektiv: Open Source WebAssembly-drevet BI"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://perspective.finos.org/",children:"Original"}),".\nPerspective er en interaktiv analyse- og datavisualiseringskomponent, designet for streaming og store datasett med konfigurerbare rapporter, dashbord og notatb\xf8ker. Den har en minneeffektiv streaming-sp\xf8rringsmotor i C++ og Python og et brukergrensesnitt pakket som et tilpasset element drevet av WebAssembly eller WebSocket. Brukergrensesnittet inkluderer interaktive dashbord som kan integreres i et hvilket som helst rammeverk for webapplikasjoner. Perspective.js er avhengig av WebAssembly og Apache Arrow for desktop-lignende ytelse i nettleseren. PerspectivePython implementerer Perspective API direkte i Python for forskning eller produksjon. Det finnes virtualiserte og skalerbare widgets, og prosjektet er tilgjengelig p\xe5 GitHub med bruker- og programmeringsveiledninger."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35455850",children:"Discussion Service"}),".\nWebAssembly-drevet BI-verkt\xf8y med \xe5pen kildekode Perspective roses for kraftig funksjonalitet, til tross for ytelsesproblemer: L\xf8sningsforslagene inkluderer bruk av et lettere alternativ. Skaperne av Perspective jobber med \xe5 forbedre ytelsen og mobilkompatibiliteten. Noen bekymringer knyttet til Firefox-st\xf8tte og tilgjengelighet/ikke-tastaturvennlig design. Begrensninger i Sciter diskutert, Tauri-biblioteker sett p\xe5 som potensielt nyttige. Det er behov for ytelsesforbedringer for Perspective-prosjektet."]}),"\n",(0,i.jsx)(r.h2,{id:"grid-world",children:"Grid World"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://alex.miller.garden/grid-world/",children:"Original"}),'.\nAlexander Millers "Grid World" utforsker rutenettets rolle i livet hans fra barndom til voksen alder, inkludert dets innvirkning p\xe5 teknologi, kunst og navigasjon. Artikkelen tar for seg kraften som rutenett har n\xe5r det gjelder \xe5 kartlegge og kontrollere rommet, slik vi ser det i spill som Battleship og Chess. Rutenettet blir et sentralt knutepunkt som knytter Millers personlige erfaringer sammen, og viser hvordan det blir en del av livene v\xe5re. Miller skapte rutenettet for The HTML Review i 2023.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35455770",children:"Discussion Service"}),".\nDiscussion Service-brukere er fascinert av den eksepsjonelle beherskelsen og h\xe5ndverket til Grid World innen webdesign og -utvikling og dens innvirkning p\xe5 persepsjon. Artikkelen utforsker nettets understruktur for v\xe5re minner og verden, med tilh\xf8rende pikselkunstbilder. Kommentarer bemerker forbindelsen til nevrovitenskap med rutenettceller, samtidig som de reiser kritikk om rasjonalisering og rutenettets teppe p\xe5 naturen. En bruker synes det er vanskelig \xe5 perfeksjonere de visuelle designaspektene ved sitt personlige prosjekt. Brukere diskuterer rutenettm\xf8nstrene til Queens og historien bak rutenettm\xf8nstrene. En Discussion Service-bruker deler innsikt i New Yorks gatenettkonformitet. En bordlignende dekorasjon genererer svakt opplyste messesaler mens den utvikler seg over tid, bygget med vanlig javascript uten noen biblioteker for morsom teknisk \xf8velse."]}),"\n",(0,i.jsx)(r.h2,{id:"openai-tokenizer",children:"OpenAI Tokenizer"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://platform.openai.com/tokenizer",children:"Original"}),".\nOpenAI API er en teknologi som krever at JavaScript er aktivert."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35453400",children:"Discussion Service"}),".\nOpenAI har gitt ut en ny tokenizer for \xe5 bedre forst\xe5 GPT-modeller. Tokenizer deler opp tekst i underordenheter for effektiv behandling, men de mangler iboende mening. Discussion Service-brukere diskuterer verkt\xf8yets begrensninger som gruppering basert p\xe5 mellomrom og behandling av store bokstaver. Kodinger opprettet ved hjelp av bytepar-koding er ofte ikke godt egnet for underrepresenterte spr\xe5k. OpenAI tar betalt per token p\xe5 grunn av modellens tokenbaserte drift."]}),"\n",(0,i.jsx)(r.h2,{id:"tabloid---programmeringsspr\xe5ket-for-clickbait-overskriftene",children:"Tabloid - programmeringsspr\xe5ket for clickbait-overskriftene"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://tabloid-thesephist.vercel.app/",children:"Original"}),".\nTabloid er et nytt programmeringsspr\xe5k laget for \xe5 generere latterlige og klikkverdige overskrifter, som ligner de man ser i tabloider. Spr\xe5ket bruker en kombinasjon av naturlig spr\xe5kbehandling, maskinl\xe6ring og crowd-sourcing for \xe5 lage overskrifter med klikkbare spr\xe5klige m\xf8nstre. Det er et morsomt og underholdende spr\xe5k som ikke tjener noe egentlig form\xe5l, men det er et utmerket eksempel p\xe5 hvordan programmering kan v\xe6re b\xe5de nyttig og underholdende. Skaperen av Tabloid planlegger \xe5 bruke det til \xe5 lage en plattform som lar hvem som helst lage sine egne clickbait-overskrifter. Discussion Service-brukere synes dette verkt\xf8yet er interessant og en nyttig m\xe5te \xe5 forst\xe5 naturlig spr\xe5kbehandling p\xe5."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35447580",children:"Discussion Service"}),'.\nEt nylig prosjekt p\xe5 Hacker News kalt Tabloid - The Clickbait Headline Programming Language. Prosjektet er fascinerende, skrevet av en forfatter som hevder \xe5 ha skrevet andre spr\xe5k som uten tvil er mer nyttige. En Discussion Service-bruker la ut et program i Tabloid som tar fem tall og returnerer produktet av de tre f\xf8rste tallene pluss produktet av de to siste. Forfatteren er en person som har sendt mange interessante prosjekter, og til og med brukt Oak til \xe5 bygge en haug med personlig programvareinfrastruktur, blant annet. En annen Discussion Service-bruker kommenterte at det \xe5 skrive alt fra bunnen av er mest levedyktig for ensomme utviklere, men ikke for team, der det er bedre \xe5 g\xe5 med "kjedelig".']}),"\n",(0,i.jsx)(r.h2,{id:"gpt4-simulerer-en-ftp-server-p\xe5-ftpdisneycom",children:"GPT4 simulerer en FTP-server p\xe5 ftp.disney.com."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.filestash.app/2023/04/01/chat-gpt-acting-as-a-ftp-server/",children:"Original"}),".\nChat GPT-4 er dyktig til \xe5 simulere en FTP-server for Disney, ved hjelp av base ftp cli-verkt\xf8yet og kommer til \xe5 utf\xf8re kommandoer som en ekte bruker ville gjort. Den simulerte serveren inneholder eksklusivt Disney-innhold i mapper som filmer, lydspor og bakgrunnsbilder, og GPT-4 viser seg i stand til \xe5 navigere i lokale og eksterne filsystemer. Den nye teknologien yter godt, overg\xe5r forventningene og demonstrerer sin evne til \xe5 skape overbevisende innhold for Disney-entusiaster. Artikkelen antyder fremtidige bruksomr\xe5der for GPT-4 i kodetolker-plugins som gir tilgang til oppdiktede servere fra FTP-klienter."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35450315",children:"Discussion Service"}),'.\nEn artikkel p\xe5 Hacker News diskuterer GPT4 som simulerer en FTP-server p\xe5 ftp.disney.com. Brukerne diskuterer hvorvidt dette kan betraktes som "hallusinerende", til tross for at AI kan simulere eller "hallusinere". N\xf8yaktigheten av AI-genererte svar og oppfatningen av disse resultatene som "hallusinasjoner" er ogs\xe5 gjenstand for diskusjon. Andre temaer som diskuteres er: potensialet for at selvgenererte filmer eller TV-serier er verdil\xf8se, rollen til latent rom og spr\xe5k i LLM, teknologiens innvirkning p\xe5 samfunnet og begrensningene i dagens AI-kapasiteter. Noen brukere advarer mot \xe5 overtolke AIs evner og p\xe5peker at begrensningene ofte blir oversett.']}),"\n",(0,i.jsx)(r.h2,{id:"bruke-mmap-for-\xe5-f\xe5-llama-til-\xe5-laste-raskere",children:"Bruke mmap for \xe5 f\xe5 LLaMA til \xe5 laste raskere."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://justine.lol/mmap/",children:"Original"}),".\nLLaMA bruker mmap() for \xe5 laste modeller 100 ganger raskere, \xf8ker RAM-stabiliteten og gj\xf8r det mulig \xe5 kj\xf8re flere prosesser samtidig. Linux-brukere f\xe5r 100x forbedring, mens Windows og MacOS f\xe5r 10x. Den nye mmap()-lasteren er n\xe5 tilgjengelig p\xe5 GitHub under MIT-lisens. Anonym samarbeidspartner @Slaren la til mmap() -st\xf8tte til LLaMA-7B, noe som gir \xf8yeblikkelig lastetid uten endring av filformat. Det nye filformatet justerer tensorer p\xe5 en 32-byte grense. Innlegget utforsker potensielle forbedringer i diskutnyttelse og ytelsesforstyrrelser. Justine Tunney skriver om Twitter og Github i standardverkt\xf8y, rettet mot eksperter p\xe5 omr\xe5det. Det er klart og konsist, uten partiskhet eller politiske eller religi\xf8se uttalelser. En Discussion Service-bruker kommenterer at Tunneys innlegg er en flott ressurs for l\xe6ring."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35455930",children:"Discussion Service"}),".\nBruk av mmap for \xe5 f\xe5 LLaMA til \xe5 laste raskere er hovedfokuset i artikkelen, til tross for drama rundt attribusjon og tekniske problemer i kommentarfeltet. Fordelene og ulempene med mmap diskuteres, i tillegg til de tekniske fordelene med Facebooks LLaMA.cpp. Brukerne diskuterer nytten av LLaMAs endringer og fordeler og ulemper ved ulike funksjoner, og gir verdifull innsikt for teknologikyndige lesere som er interessert i \xe5 l\xe6re mer om AI og modellimplementering. Innlegget fremhever en systemteknisk tiln\xe6rming til et problem og en trend som involverer propriet\xe6r kode i biblioteker, og genererer diskusjon om bruken av Huge Pages og vanskeligheten med \xe5 l\xf8se IO-flaskehalser. Den revolusjonerende ytelsesforbedringen ved bruk av mmap har fanget oppmerksomheten til eksperter p\xe5 omr\xe5det."]})]})}function g(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}}}]);